CREATE TABLE [dbo].[ccoCallbacks](	  [callout_id] INT NULL	, [user_id] INT NULL	, [cam_id] INT NULL	, [cal_key] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [cal_telefono] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [cal_telCB] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [cal_fecha] DATETIME NULL	, [cal_fusercallback] DATETIME NULL	, [cal_fcallback] DATETIME NULL	, [status] TINYINT NULL	, [schedulerStatus] TINYINT NULL)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks] ON [dbo].[ccoCallbacks] ([callout_id] ASC, [status] ASC)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks2] ON [dbo].[ccoCallbacks] ([schedulerStatus] ASC)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks3] ON [dbo].[ccoCallbacks] ([schedulerStatus] ASC, [callout_id] ASC)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks4] ON [dbo].[ccoCallbacks] ([schedulerStatus] ASC, [status] ASC)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks5] ON [dbo].[ccoCallbacks] ([cal_fecha] ASC)CREATE NONCLUSTERED INDEX [IX_ccoCallBacks6] ON [dbo].[ccoCallbacks] ([callout_id] ASC)